def pick(xs: list[int], seed: int) -> int:
    """Return an element of the non-empty list xs, chosen from seed.

    The same (xs, seed) pair always returns the same element.
    No randomness is used.
    """
    return xs[seed % len(xs)]


def test_pick_returns_member() -> None:
    xs = [10, 20, 30]
    for seed in range(20):
        assert pick(xs, seed) in xs


def test_pick_same_seed_same_element() -> None:
    xs = [4, 8, 15, 16, 23, 42]
    for seed in range(10):
        assert pick(xs, seed) == pick(xs, seed)


def test_pick_same_seed_across_equal_lists() -> None:
    assert pick([1, 2, 3, 4], 7) == pick([1, 2, 3, 4], 7)


def test_pick_single_element() -> None:
    assert pick([7], 0) == 7
    assert pick([7], -5) == 7
    assert pick([7], 12345) == 7


def test_pick_negative_seed_is_deterministic() -> None:
    xs = [5, 6, 7, 8]
    assert pick(xs, -3) == pick(xs, -3)
    assert pick(xs, -3) in xs


def test_pick_varies_with_seed() -> None:
    xs = list(range(10))
    results = {pick(xs, seed) for seed in range(10)}
    assert len(results) > 1
